import{_ as e,C as r,c as t,o as n,j as i,G as l,b as a,a0 as s,a as o,w as d,a1 as k}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Ernæring for presisjonsytelse","description":"","frontmatter":{},"headers":[],"relativePath":"no/education/nutrition/index.md","filePath":"no/education/nutrition/index.md"}');const p=e({name:"no/education/nutrition/index.md"},[["render",function(e,g,p,u,m,h){const b=r("AdBanner"),f=r("Mermaid"),v=r("AdInArticle");return n(),t("div",null,[g[2]||(g[2]=i("h1",{id:"ernæring-for-presisjonsytelse",tabindex:"-1"},[o("Ernæring for presisjonsytelse "),i("a",{class:"header-anchor",href:"#ernæring-for-presisjonsytelse","aria-label":'Permalink to "Ernæring for presisjonsytelse"'},"​")],-1)),l(b),g[3]||(g[3]=i("p",null,[o("Pétanque er en presisjonssport, ikke en utholdenhetssport. Dine ernæringsbehov er annerledes enn en maratonløper eller en fotballspiller. Det som betyr mest er "),i("strong",null,"hjernens drivstoffstabilitet"),o(" – å holde hjernen skarp og hendene stødige gjennom en lang konkurransedag.")],-1)),g[4]||(g[4]=i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"Den store ideen"),i("p",null,[i("strong",null,"Hjernen din er ditt viktigste verktøy i petanque. Gi den stabil drivstoff, ikke berg-og-dal-bane-energi."),o(" Fokuser på protein, sunt fett og å holde deg hydrert. Unngå sukkertopper.")])],-1)),(n(),a(k,null,{default:d(()=>[l(f,{id:"mermaid-13",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BSukker%2Fenkle%20karbohydrater%5D%20--%3E%20B%5BBlodsukkertopp%5D%0A%20%20%20%20B%20--%3E%20C%5BInsulinfrigj%C3%B8ring%5D%0A%20%20%20%20C%20--%3E%20D%5BBlodsukkerkrasj%5D%0A%20%20%20%20D%20--%3E%20E%5BAdrenalinrespons%5D%0A%20%20%20%20E%20--%3E%20F%5BTremor%20og%20angst%5D%0A%0A%20%20%20%20G%5BProtein%20og%20sunt%20fett%5D%20--%3E%20H%5BStabilt%20blodsukker%5D%0A%20%20%20%20H%20--%3E%20I%5BKonsekvent%20energi%5D%0A%20%20%20%20I%20--%3E%20J%5BSkarpt%20fokus%5D%0A%20%20%20%20J%20--%3E%20K%5BSt%C3%B8dige%20hender%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%0A%20%20%20%20style%20K%20fill%3A%23e8f5e9%0A"})]),fallback:d(()=>[...g[0]||(g[0]=[o(" Loading... ",-1)])]),_:1})),g[5]||(g[5]=s('<h2 id="presisjonsutøverens-utfordring" tabindex="-1">Presisjonsutøverens utfordring <a class="header-anchor" href="#presisjonsutøverens-utfordring" aria-label="Permalink to &quot;Presisjonsutøverens utfordring&quot;">​</a></h2><p>I motsetning til høyintensitetssport krever ikke pétanque massive glykogenlagre eller rask energipåfylling. Det den krever er:</p><ul><li><strong>Stabilt blodsukker</strong> – ingen topper eller krasj</li><li><strong>Konsekvent mental klarhet</strong> – fokus som varer hele dagen</li><li><strong>Stødige hender</strong> - ingen skjelvinger eller risting</li><li><strong>Rolige nerver</strong> – lav angst og stressrespons</li></ul><p>Ernæringsstrategien din bør optimalisere for disse faktorene, ikke for rå energiproduksjon.</p><h2 id="problemet-med-sukker-og-enkle-karbohydrater" tabindex="-1">Problemet med sukker og enkle karbohydrater <a class="header-anchor" href="#problemet-med-sukker-og-enkle-karbohydrater" aria-label="Permalink to &quot;Problemet med sukker og enkle karbohydrater&quot;">​</a></h2><p>Mange idrettsutøvere går som standard til et karbohydratrikt kosthold. For petanque-spillere kan dette faktisk gå utover prestasjonene.</p><h3 id="blodsukkerberg-og-dal-banen" tabindex="-1">Blodsukkerberg-og-dal-banen <a class="header-anchor" href="#blodsukkerberg-og-dal-banen" aria-label="Permalink to &quot;Blodsukkerberg-og-dal-banen&quot;">​</a></h3><p>Når du spiser sukker eller enkle karbohydrater:</p><ol><li>Blodsukkeret stiger raskt</li><li>Insulin frigjøres for å senke det</li><li>Blodsukkeret faller (hypoglykemi)</li><li>Kroppen din frigjør adrenalin for å kompensere</li><li>Du opplever skjelvinger, angst og dårlig fokus</li></ol><p><strong>Dette er det motsatte av hva du trenger for presisjon.</strong></p><h3 id="symptomer-pa-ustabilitet-i-blodsukkeret" tabindex="-1">Symptomer på ustabilitet i blodsukkeret <a class="header-anchor" href="#symptomer-pa-ustabilitet-i-blodsukkeret" aria-label="Permalink to &quot;Symptomer på ustabilitet i blodsukkeret&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Innvirkning på ytelse</th></tr></thead><tbody><tr><td>Skjelvende hender</td><td>Inkonsekvent utgivelse</td></tr><tr><td>Vanskeligheter med å konsentrere seg</td><td>Dårlig beslutningstaking</td></tr><tr><td>Irritabilitet</td><td>Lagkonflikt, dårlig ro</td></tr><tr><td>Tretthet etter måltider</td><td>Ettermiddagsnedgang</td></tr><tr><td>Angst</td><td>Trykkfølsomhet</td></tr><tr><td>Hjernetåke</td><td>Langsom taktisk tenkning</td></tr></tbody></table><h2 id="en-bedre-tilnærming-stabil-energi" tabindex="-1">En bedre tilnærming: Stabil energi <a class="header-anchor" href="#en-bedre-tilnærming-stabil-energi" aria-label="Permalink to &quot;En bedre tilnærming: Stabil energi&quot;">​</a></h2><p>Målet er å gi hjernen din jevnlig drivstoff uten berg-og-dal-banen.</p><h3 id="viktige-prinsipper" tabindex="-1">Viktige prinsipper <a class="header-anchor" href="#viktige-prinsipper" aria-label="Permalink to &quot;Viktige prinsipper&quot;">​</a></h3><ol><li><strong>Prioriter protein og sunt fett</strong> – De gir langsom, jevn energi</li><li><strong>Velg komplekse karbohydrater fremfor enkle</strong> – Hvis du spiser karbohydrater, velg de som fordøyes sakte</li><li><strong>Unngå sukkertopper</strong> – Spesielt før og under konkurranse</li><li><strong>Hold deg hydrert</strong> - Dehydrering påvirker konsentrasjonen betydelig</li><li><strong>Spis regelmessig</strong> - Ikke la deg bli for sulten</li></ol><h3 id="matvarer-som-hjelper" tabindex="-1">Matvarer som hjelper <a class="header-anchor" href="#matvarer-som-hjelper" aria-label="Permalink to &quot;Matvarer som hjelper&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mattype</th><th>Eksempler</th><th>Hvorfor det fungerer</th></tr></thead><tbody><tr><td>Protein</td><td>Egg, nøtter, ost, kjøtt</td><td>Langsom fordøyelse, stabil energi</td></tr><tr><td>Sunne fettsyrer</td><td>Avokado, olivenolje, nøtter</td><td>Langvarig drivstoff</td></tr><tr><td>Komplekse karbohydrater</td><td>Grønnsaker, belgfrukter</td><td>Fiber forsinker absorpsjonen</td></tr><tr><td>Frukt med lavt sukkerinnhold</td><td>Bær, epler</td><td>Næringsstoffer uten pigg</td></tr></tbody></table><h3 id="matvarer-a-begrense" tabindex="-1">Matvarer å begrense <a class="header-anchor" href="#matvarer-a-begrense" aria-label="Permalink to &quot;Matvarer å begrense&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mattype</th><th>Eksempler</th><th>Hvorfor det er problematisk</th></tr></thead><tbody><tr><td>Sukker</td><td>Godteri, brus, bakverk</td><td>Rask topp og krasj</td></tr><tr><td>Hvitt brød/pasta</td><td>Smørbrød, pastaretter</td><td>Rask omdannelse til sukker</td></tr><tr><td>Fruktjuice</td><td>Appelsinjuice, smoothies</td><td>Konsentrert sukker</td></tr><tr><td>Energidrikker</td><td>De fleste kommersielle merkene</td><td>Sukker + koffein-krasj</td></tr></tbody></table><h2 id="ernæring-pa-konkurransedagen" tabindex="-1">Ernæring på konkurransedagen <a class="header-anchor" href="#ernæring-pa-konkurransedagen" aria-label="Permalink to &quot;Ernæring på konkurransedagen&quot;">​</a></h2><h3 id="før-konkurransen" tabindex="-1">Før konkurransen <a class="header-anchor" href="#før-konkurransen" aria-label="Permalink to &quot;Før konkurransen&quot;">​</a></h3><p><strong>2–3 timer før:</strong></p><ul><li>Balansert måltid med protein, fett og grønnsaker</li><li>Unngå tunge karbohydrater som kan forårsake døsighet</li><li>Eksempel: Egg med grønnsaker, eller salat med kylling</li></ul><p><strong>1 time før:</strong></p><ul><li>Lett snacks om nødvendig</li><li>Nøtter, ost eller en liten porsjon protein</li><li>Unngå alt som er sukkerholdig</li></ul><h3 id="under-konkurransen" tabindex="-1">Under konkurransen <a class="header-anchor" href="#under-konkurransen" aria-label="Permalink to &quot;Under konkurransen&quot;">​</a></h3><p><strong>Mellom kampene:</strong></p><ul><li>Vann (viktigst)</li><li>Små proteinsnacks (nøtter, ost, kjøtt)</li><li>Unngå sukkerholdige snacks og drikker</li></ul><p><strong>Tegn på at du må spise:</strong></p><ul><li>Vanskeligheter med å konsentrere seg</li><li>Irritabilitet</li><li>Føler seg skjelven</li><li>Hodepine</li></ul><h3 id="etter-konkurransen" tabindex="-1">Etter konkurransen <a class="header-anchor" href="#etter-konkurransen" aria-label="Permalink to &quot;Etter konkurransen&quot;">​</a></h3><ul><li>Fyll på med et balansert måltid</li><li>Rehydrer fullstendig</li><li>Ikke «belønn» deg selv med sukker – det vil påvirke restitusjonen din.</li></ul><h2 id="hydrering" tabindex="-1">Hydrering <a class="header-anchor" href="#hydrering" aria-label="Permalink to &quot;Hydrering&quot;">​</a></h2><p>Dehydrering påvirker kognitiv funksjon før du føler deg tørst.</p><h3 id="retningslinjer" tabindex="-1">Retningslinjer <a class="header-anchor" href="#retningslinjer" aria-label="Permalink to &quot;Retningslinjer&quot;">​</a></h3><ul><li><strong>Start med å drikke vann</strong> - Drikk vann i løpet av dagen før konkurransen</li><li><strong>Under lek</strong> - Drikk vann regelmessig, ikke vent til du er tørst</li><li><strong>Unngå for mye koffein</strong> – Det er vanndrivende</li><li><strong>Se etter tegn</strong> - Hodepine, mørk urin, tretthet</li></ul><h3 id="hvor-mye" tabindex="-1">Hvor mye? <a class="header-anchor" href="#hvor-mye" aria-label="Permalink to &quot;Hvor mye?&quot;">​</a></h3><p>En generell retningslinje: sikt mot blekgul urin. Hvis den er mørk, trenger du mer vann.</p><h2 id="lavkarbo-alternativet" tabindex="-1">Lavkarbo-alternativet <a class="header-anchor" href="#lavkarbo-alternativet" aria-label="Permalink to &quot;Lavkarbo-alternativet&quot;">​</a></h2><p>Noen presisjonsutøvere følger lavkarbo- eller ketogene dietter. Teorien:</p><p><strong>Potensielle fordeler:</strong></p><ul><li>Svært stabilt blodsukker (ingen topper mulig)</li><li>Konsekvent mental klarhet</li><li>Redusert angst og skjelvinger</li><li>Ingen energikrasj ettermiddagen</li></ul><p><strong>Hensyn:</strong></p><ul><li>Krever tilpasningsperiode (1–2 uker)</li><li>Ikke egnet for alle</li><li>Krever planlegging og engasjement</li><li>Rådfør deg med helsepersonell først</li></ul>',45)),l(v),g[6]||(g[6]=s('<p>Dette er en avansert strategi – ikke nødvendig for alle, men verdt å vurdere hvis blodsukkerstabilitet er et betydelig problem for deg.</p><h2 id="mat-som-øvelse-tren-kroppen-din" tabindex="-1">Mat som øvelse: Tren kroppen din <a class="header-anchor" href="#mat-som-øvelse-tren-kroppen-din" aria-label="Permalink to &quot;Mat som øvelse: Tren kroppen din&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Kritisk konsept</p><p><strong>Mat er ikke bare drivstoff – det er noe du trener med.</strong> Akkurat som du trener på kastet ditt, må du øve på ernæringen din for å gjøre kroppen komfortabel med å spise på konkurransedagen.</p></div><h3 id="hvorfor-matpraksis-er-viktig" tabindex="-1">Hvorfor matpraksis er viktig <a class="header-anchor" href="#hvorfor-matpraksis-er-viktig" aria-label="Permalink to &quot;Hvorfor matpraksis er viktig&quot;">​</a></h3><p>Fordøyelsessystemet ditt er trenbart. Det du spiser regelmessig blir det kroppen din forventer og håndterer best. Hvis du bare spiser protein og grønnsaker på konkurransedager, vil ikke kroppen din være tilpasset det.</p><p><strong>Problemet:</strong></p><ul><li>Å spise ukjent mat på konkurransedagen kan forårsake fordøyelsesbesvær</li><li>Kroppen din trenger tid til å tilpasse seg nye spisemønstre</li><li>Stress + ukjent mat = potensielle mageproblemer</li><li>Prestasjonsangst er ille nok uten å legge til fordøyelsesangst</li></ul><p><strong>Løsningen:</strong></p><ul><li>Øv på konkurranseernæring under trening</li><li>Gjør konkurransedagsmaten til en del av din vanlige rutine</li><li>Tren kroppen din til å bli komfortabel med mat med stabil energi</li></ul><h3 id="tilpasningsprosessen" tabindex="-1">Tilpasningsprosessen <a class="header-anchor" href="#tilpasningsprosessen" aria-label="Permalink to &quot;Tilpasningsprosessen&quot;">​</a></h3>',10)),(n(),a(k,null,{default:d(()=>[l(f,{id:"mermaid-590",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BN%C3%A5v%C3%A6rende%20kosthold%5D%20--%3E%20B%5BGradvise%20endringer%5D%0A%20%20%20%20B%20--%3E%20C%5BKroppstilpasning%20%3Cbr%2F%3E%202%E2%80%934%20uker%5D%0A%20%20%20%20C%20--%3E%20D%5BNy%20normal%5D%0A%20%20%20%20D%20--%3E%20E%5BKonkurranseklar%5D%0A%0A%20%20%20%20F%5BPlutselig%20endring%20%3Cbr%2F%3E%20Konkurransedagen%5D%20--%3E%20G%5BFord%C3%B8yelsesbesv%C3%A6r%5D%0A%20%20%20%20G%20--%3E%20H%5BD%C3%A5rlig%20ytelse%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff3e0%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23ffebee%0A%20%20%20%20style%20H%20fill%3A%23ffebee%0A"})]),fallback:d(()=>[...g[1]||(g[1]=[o(" Loading... ",-1)])]),_:1})),g[7]||(g[7]=s('<p>Når du endrer kostholdet ditt:</p><ol><li><strong>Uke 1–2:</strong> Kroppen din tilpasser seg ny mat, men den kan føles annerledes</li><li><strong>Uke 3–4:</strong> Tilpasning skjer, ny mat føles normal</li><li><strong>Uke 5+:</strong> Kroppen din er komfortabel og effektiv med disse matvarene</li></ol><p><strong>Det er derfor du ikke bare kan «spise sunt» på konkurransedagen og forvente optimale resultater.</strong></p><h3 id="slik-praktiserer-du-ernæringen-din" tabindex="-1">Slik praktiserer du ernæringen din <a class="header-anchor" href="#slik-praktiserer-du-ernæringen-din" aria-label="Permalink to &quot;Slik praktiserer du ernæringen din&quot;">​</a></h3><h4 id="_1-start-under-trening" tabindex="-1">1. Start under trening <a class="header-anchor" href="#_1-start-under-trening" aria-label="Permalink to &quot;1. Start under trening&quot;">​</a></h4><p><strong>Øv på konkurransedagsspising under treningsøktene:</strong></p><ul><li>Spis det samme måltidet før trening som du ville spist før konkurranse</li><li>Ta med de samme snacksene som du ville tatt med til en turnering</li><li>Legg merke til hvordan kroppen din reagerer</li><li>Juster basert på hva som fungerer</li></ul><p><strong>Eksempel på treningsdag:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2-3 hours before: Eggs with vegetables (same as competition)</span></span>\n<span class="line"><span>During training: Water + nuts (same as competition)</span></span>\n<span class="line"><span>After training: Balanced meal with protein</span></span></code></pre></div><h4 id="_2-gjør-det-til-din-normale" tabindex="-1">2. Gjør det til din normale <a class="header-anchor" href="#_2-gjør-det-til-din-normale" aria-label="Permalink to &quot;2. Gjør det til din normale&quot;">​</a></h4><p><strong>Hvis du ikke har en «konkurransediett» og en «vanlig diett»</strong> – dette skaper to problemer:</p><ul><li>Kroppen din tilpasser seg aldri helt til noen av delene</li><li>Konkurransemat føles uvant og stressende</li></ul><p><strong>I stedet:</strong></p><ul><li>Gjør mat med stabil energi til din daglige norm</li><li>Kroppen din blir effektiv til å bruke protein og fett</li><li>Konkurransedagen føles normal, ikke annerledes</li><li>Ingen fordøyelsesoverraskelser</li></ul><h4 id="_3-test-og-finjuster" tabindex="-1">3. Test og finjuster <a class="header-anchor" href="#_3-test-og-finjuster" aria-label="Permalink to &quot;3. Test og finjuster&quot;">​</a></h4><p><strong>Bruk trening til å eksperimentere:</strong></p><table tabindex="0"><thead><tr><th>Test</th><th>Hva du bør legge merke til</th><th>Justere</th></tr></thead><tbody><tr><td>Måltidspunkt før trening</td><td>Energinivåer, fokus</td><td>Finn ditt optimale vindu</td></tr><tr><td>Ulike proteinkilder</td><td>Fordøyelse, komfort</td><td>Identifiser hva som fungerer best</td></tr><tr><td>Snacktyper</td><td>Vedvarende energi</td><td>Finn dine favorittsnacks</td></tr><tr><td>Hydreringsmengder</td><td>Konsentrasjon, toalettpauser</td><td>Balanseinntak</td></tr></tbody></table><p><strong>Før en enkel logg:</strong></p><ul><li>Hva du spiste og når</li><li>Hvordan du følte deg under treningen</li><li>Energinivåer og fokus</li><li>Eventuelle fordøyelsesproblemer</li></ul><h4 id="_4-bygg-komfort-og-selvtillit" tabindex="-1">4. Bygg komfort og selvtillit <a class="header-anchor" href="#_4-bygg-komfort-og-selvtillit" aria-label="Permalink to &quot;4. Bygg komfort og selvtillit&quot;">​</a></h4><p><strong>Den psykologiske fordelen:</strong></p><p>Når du har øvd på ernæringen din hundrevis av ganger på trening:</p><ul><li>Du vet nøyaktig hvordan kroppen din vil reagere</li><li>Ingen bekymring for matvalg</li><li>Én ting mindre å bekymre seg for på konkurransedagen</li><li>Tillit til forberedelsene dine</li></ul><p><strong>Dette er samme prinsipp som å øve på kastet ditt</strong> – repetisjon bygger komfort og pålitelighet.</p><h3 id="vanlige-tilpasningsutfordringer" tabindex="-1">Vanlige tilpasningsutfordringer <a class="header-anchor" href="#vanlige-tilpasningsutfordringer" aria-label="Permalink to &quot;Vanlige tilpasningsutfordringer&quot;">​</a></h3><details class="details custom-block"><summary>Overgang fra høykarbohydratkosthold til stabilt energikosthold</summary><p><strong>Utfordring:</strong> Du er vant til brød, pasta og sukkerholdige snacks</p><p><strong>Tilpasningsperiode:</strong> 2–4 uker</p><p><strong>Hva du kan forvente:</strong></p><ul><li>Uke 1: Kan føles annerledes, lyst på gammel mat</li><li>Uke 2: Energien stabiliserer seg, suget reduseres</li><li>Uke 3-4: Ny normal, kroppen er effektiv med fett/protein</li></ul><p><strong>Slik øver du:</strong></p><ul><li>Start med ett måltid om gangen</li><li>Bytt ut enkle karbohydrater med komplekse karbohydrater først</li><li>Øk gradvis protein og sunt fett</li><li>Øv først under trening med lav innsats</li></ul></details><details class="details custom-block"><summary>Finne matvarer som fungerer for deg</summary><p><strong>Utfordring:</strong> Ikke alle fordøyer den samme maten godt</p><p><strong>Hva skal testes:</strong></p><ul><li>Ulike proteinkilder (egg vs. kjøtt vs. nøtter)</li><li>Måltidspunkt (2 timer vs. 3 timer før)</li><li>Porsjonsstørrelser (for mye = treg, for lite = sulten)</li><li>Spesifikke matvarer som forårsaker ubehag</li></ul><p><strong>Øvingsmetoden:</strong></p><ul><li>Prøv én variabel om gangen</li><li>Gi 2–3 treningsøkter til hver test</li><li>Legg merke til hva som får deg til å føle deg best</li><li>Lag din personlige «konkurransemeny»</li></ul></details><details class="details custom-block"><summary>Håndtering av turneringsmatmiljøer</summary><p><strong>Utfordring:</strong> Turneringer har ofte begrensede matalternativer</p><p><strong>Øvingsløsning:</strong></p><ul><li>Ta alltid med egen snacks (øv på dette)</li><li>Undersøk steder på forhånd når det er mulig</li><li>Ha sikkerhetskopieringsalternativer du vet fungerer</li><li>Øv på å spise i forskjellige miljøer</li></ul><p><strong>Mental forberedelse:</strong></p><ul><li>Ikke stol på maten på stedet</li><li>Behandle mat som en del av utstyret ditt</li><li>Pakk det slik du pakker boulene dine</li></ul></details><h3 id="_30-dagers-ernæringspraksisplan" tabindex="-1">30-dagers ernæringspraksisplan <a class="header-anchor" href="#_30-dagers-ernæringspraksisplan" aria-label="Permalink to &quot;30-dagers ernæringspraksisplan&quot;">​</a></h3><p><strong>Mål:</strong> Gjør stabil energikost til din komfortable normal</p><p><strong>Uke 1–2: Grunnleggende behandling</strong></p><ul><li>Erstatt ett måltid per dag med konkurranseinspirert kosthold</li><li>Øv på ernæring før trening</li><li>Begynn å ta med snacks på trening</li><li>Legg merke til hvordan kroppen din reagerer</li></ul><p><strong>Uke 3–4: Utvidelse</strong></p><ul><li>Gjør to måltider per dag stabilt energifokusert</li><li>Øv på å spise hele konkurransedagen på treningsdager</li><li>Avgrens snackvalgene dine</li><li>Lag din egen liste over matvarer</li></ul><p><strong>Uke 5+: Mestring</strong></p><ul><li>Stabil energispising er din nye normal</li><li>Kroppen er fullt tilpasset</li><li>Konkurransedagen føles rutinemessig</li><li>Tillit til ernæringen din</li></ul><h3 id="ditt-konkurransematsett" tabindex="-1">Ditt konkurransematsett <a class="header-anchor" href="#ditt-konkurransematsett" aria-label="Permalink to &quot;Ditt konkurransematsett&quot;">​</a></h3><p><strong>Øv på å pakke dette til hver treningsøkt:</strong></p><p><strong>Før konkurransen (2–3 timer før):</strong></p><ul><li>[ ] Proteinkilde (egg, kjøtt eller nøtter)</li><li>[ ] Grønnsaker eller salat</li><li>[ ] Sunt fett (avokado, olivenolje, ost)</li></ul><p><strong>Under konkurransen:</strong></p><ul><li>[ ] Vannflaske (påfyllbar)</li><li>[ ] Blandede nøtter (små porsjoner)</li><li>[ ] Hardkokte egg (hvis du kan holde deg kjølig)</li><li>[ ] Ostebiter eller strengost</li><li>[ ] Jerky eller tørket kjøtt</li><li>[ ] Reservesnacks</li></ul><p><strong>Jo mer du øver med dette settet, desto mer automatisk blir det.</strong></p><h2 id="praktiske-tips" tabindex="-1">Praktiske tips <a class="header-anchor" href="#praktiske-tips" aria-label="Permalink to &quot;Praktiske tips&quot;">​</a></h2><h3 id="enkle-konkurransesnacks" tabindex="-1">Enkle konkurransesnacks <a class="header-anchor" href="#enkle-konkurransesnacks" aria-label="Permalink to &quot;Enkle konkurransesnacks&quot;">​</a></h3><ul><li>Blandede nøtter (usaltet)</li><li>Hardkokte egg</li><li>Osteterninger</li><li>Jerky av oksekjøtt eller kalkun</li><li>Grønnsaker med hummus</li><li>Oliven</li></ul><h3 id="hva-du-bør-unnga" tabindex="-1">Hva du bør unngå <a class="header-anchor" href="#hva-du-bør-unnga" aria-label="Permalink to &quot;Hva du bør unngå&quot;">​</a></h3><ul><li>Salgsautomat snacks</li><li>Sukkerholdige sportsdrikker</li><li>Bakverk og bakevarer</li><li>Godteri og sjokoladebarer</li><li>De fleste «energi»-barer (sjekk sukkerinnholdet)</li></ul><h2 id="viktig-konklusjon" tabindex="-1">Viktig konklusjon <a class="header-anchor" href="#viktig-konklusjon" aria-label="Permalink to &quot;Viktig konklusjon&quot;">​</a></h2><blockquote><p>Hjernen din er ditt viktigste verktøy i petanque. Gi den stabil drivstoff, ikke berg-og-dal-bane-energi. Og øv på ernæringen din akkurat som du øver på kastet ditt – repetisjon bygger komfort og pålitelighet.</p></blockquote><p>Fokuser på protein, sunt fett og å holde deg hydrert. Unngå sukkertopper. <strong>Viktigst av alt: gjør konkurransedagsnæringen din til din daglige ernæring.</strong> Kroppen din trenger trening for å yte sitt beste.</p><p><strong>Husk:</strong> Du ville ikke dukke opp i en turnering med en kasteteknikk du aldri har øvd på. Ikke møt opp med en ernæringsstrategi du aldri har øvd på heller.</p>',52)),l(b)])}]]);export{g as __pageData,p as default};
